using System.Data;
using System.Text.Json;
namespace WinFormsApp2;
internal sealed partial class ProjectReportService
{
    private async Task DeliverFiscalCsvAsync(Guid project,string report,Func<byte[],CancellationToken,Task> deliver,CancellationToken ct,AccountingApp.Contracts.FinancialFilter? filter)
    {
        string[] parts=report.Split('.');if(parts.Length!=2||!Guid.TryParseExact(parts[0],"D",out Guid id)||parts[1] is not("Summary" or "Lines"))throw new ArgumentException("Kesin mali dönem raporu geçersiz.");if(filter!=null&&(filter.From.HasValue||filter.To.HasValue||!string.IsNullOrWhiteSpace(filter.Person)))throw new ArgumentException("Kesin kayıt sonradan filtrelenmez; dönem ve sabit bölüm seçin.");_ =AuditContext.ValidateReason(AuditContext.Reason??"");
        await using var w=await SqlUnitOfWork.OpenAsync(connectionString,ct);await FiscalPeriodService.AuthorizeAsync(w,user,project,false,ct);await ProjectAuthorization.DemandAsync(w,user,project,ProjectAccess.Export,ct);var s=await FiscalPeriodService.LoadSnapshotAsync(w,project,id,ct);var source=parts[1]=="Summary"?FiscalPeriodService.Summary(s.Opening,s.Period,s.Cumulative):FiscalPeriodService.LinesTable(s.Lines);
        using var data=new DataTable();foreach(string title in new[]{"Proje","Kapanış kimliği","Önceki kapanış","Dönem başlangıcı","Dönem bitişi","Kesinleştirme UTC","Kesinleştiren","Kapsam","Kesin kayıt SHA-256"})data.Columns.Add(title);foreach(DataColumn c in source.Columns)data.Columns.Add(FiscalPresentation.Titles.GetValueOrDefault(c.ColumnName,c.ColumnName),c.DataType);
        foreach(DataRow row in source.Rows){var values=new object[source.Columns.Count+9];values[0]=s.ProjectCaption;values[1]=id.ToString("D");values[2]=s.PreviousClosingId?.ToString("D")??"";values[3]=s.FromDay.ToString("yyyy-MM-dd");values[4]=s.ToDay.ToString("yyyy-MM-dd");values[5]=s.ClosedUtc.ToString("O");values[6]=s.ClosedBy;values[7]="Kesin mali kayıt; İstanbul kayıt günleri; canlı veri değildir";values[8]=s.StoredHash;for(int i=0;i<source.Columns.Count;i++){object value=row[i];if(source.Columns[i].ColumnName is "SourceKind" or "OriginKind" or "Bucket" or "LinkKind"&&value is string text)value=FiscalPresentation.Value(text);values[i+9]=value;}data.Rows.Add(values);}
        if(data.Rows.Count==0){var empty=data.NewRow();empty[0]=s.ProjectCaption;empty[1]=id.ToString("D");empty[3]=s.FromDay.ToString("yyyy-MM-dd");empty[4]=s.ToDay.ToString("yyyy-MM-dd");empty[7]="Bu kesin bölümde kaynak olayı yok";empty[8]=s.StoredHash;data.Rows.Add(empty);}
        string path=Path.Combine(Path.GetTempPath(),"AccountingApp-fiscal-"+Guid.NewGuid().ToString("N")+".csv");try{await Task.Run(()=>ReportExport.Csv(data,path),ct);byte[] bytes=await File.ReadAllBytesAsync(path,ct);if(bytes.Length>32*1024*1024)throw new InvalidOperationException("CSV boyut sınırı aşıldı.");using var audit=w.Command(@"INSERT dbo.AuditLog(Actor,Action,EntityType,RecordKey,Operation,Reason,ReasonSource,NewValues,ActorAccountId,CorrelationId,SqlPrincipal,Source)
 VALUES(@actor,N'FiscalPeriod.Export',N'FiscalPeriodClosing',@id,N'Export',CONVERT(nvarchar(500),SESSION_CONTEXT(N'Audit.Reason')),N'UserProvided',@details,TRY_CONVERT(uniqueidentifier,SESSION_CONTEXT(N'Audit.ActorId')),TRY_CONVERT(uniqueidentifier,SESSION_CONTEXT(N'Audit.Correlation')),ORIGINAL_LOGIN(),N'Application')");audit.Text("@actor",user.Username);audit.Text("@id",id.ToString("D"),100);audit.Text("@details",JsonSerializer.Serialize(new{ProjectId=project,Section=parts[1],Rows=source.Rows.Count,ClosedUtc=s.ClosedUtc}),-1);await audit.ExecuteNonQueryAsync(ct);await deliver(bytes,ct);await w.CommitAsync(ct);}finally{if(File.Exists(path))File.Delete(path);}
    }
}
